package com.quickcart.controller; import com.quickcart.entity.*; import com.quickcart.dto.AddressRequest; import com.quickcart.service.CustomerService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/customers") public class CustomerController {final CustomerService s;CustomerController(CustomerService x){s=x;} @PostMapping Customer create(@RequestBody Map<String,String> r){return s.create(r.getOrDefault("name","Guest Customer"),r.getOrDefault("mobile",""),r.getOrDefault("email",""));} @GetMapping("/{id}") Customer get(@PathVariable Long id){return s.get(id);} @PostMapping("/{id}/addresses") Address add(@PathVariable Long id,@RequestBody AddressRequest r){return s.add(id,r);} @GetMapping("/{id}/addresses") List<Address> addresses(@PathVariable Long id){return s.list(id);} }
